const r = await tools.exec_command({cmd:"python - <<'PY'
import h5py, pandas as pd, numpy as np, pathlib, re, collections, traceback
root=pathlib.Path('data/visual-behavior-ophys-1.1.0/behavior_ophys_experiments')
files={int(re.search(r'(\d+)\.nwb$',p.name).group(1)):p for p in root.glob('*.nwb')}
T=pd.read_csv('data/visual-behavior-ophys-1.1.0/project_metadata/ophys_experiment_table.csv').set_index('ophys_experiment_id')
ids=[i for i in sorted(files) if T.loc[i,'behavior_type']=='active_behavior']
stats=[]; images=collections.Counter(); errs=[]
for k,i in enumerate(ids):
 try:
  with h5py.File(files[i],'r') as f:
   tr=f['intervals/trials']; op=f['processing/ophys/event_detection']
   nt=len(tr['id']); keep=np.asarray(tr['go'])|np.asarray(tr['catch']); keep &= ~np.asarray(tr['aborted']); keep &= ~np.asarray(tr['auto_rewarded'])
   valid=np.asarray(f['processing/ophys/image_segmentation/cell_specimen_table/valid_roi'])
   ts=np.asarray(op['timestamps'])
   eye='acquisition/EyeTracking/pupil_tracking/area' in f
   # task interval group = group containing image_name, select one with active any
   gs=[]
   for n,g in f['intervals'].items():
    if 'image_name' in g:
     vals=np.asarray(g['image_name']).astype(str)
     for x in vals: images[x]+=1
     gs.append((n,len(vals)))
   outcomes=np.stack([np.asarray(tr[x]) for x in ['hit','miss','false_alarm','correct_reject']])[:,keep]
   stats.append((i,nt,int(keep.sum()),len(valid),int(valid.sum()),len(ts),float(np.median(np.diff(ts))),eye,int(np.sum(outcomes.sum(0)!=1)),gs))
 except Exception as e: errs.append((i,repr(e),traceback.format_exc()))
print('active ids',len(ids),'ok',len(stats),'errors',errs)
a=np.array([x[1:9] for x in stats],dtype=object)
labels=['all_trials','kept_trials','rois','valid_rois','timestamps','median_dt','has_eye','bad_outcome']
for j,l in enumerate(labels):
 col=np.array([x[j+1] for x in stats])
 if col.dtype==bool: print(l,collections.Counter(col))
 else:
  try: print(l,'sum',col.sum(),'min',col.min(),'median',np.median(col),'max',col.max())
  except: print(l,collections.Counter(col))
print('dt rounded',collections.Counter(round(x[6],4) for x in stats))
print('zero keep',[x[0] for x in stats if x[2]<2])
print('zero rois',[x[0] for x in stats if x[4]<1])
print('missing eye',[x[0] for x in stats if not x[7]])
print('images',images)
print('interval groups sample')
for x in stats[:10]:print(x[0],x[-1])
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":30000});
text(r.output);

